#!/usr/bin/env bash
# tools/gen_xyz_configs.sh — (re)generate record/config-*-xyz.yaml.
#
# xyz configs are GENERATED — do not edit by hand. They are the base
# record/config-sndk.yaml template with four mechanical substitutions:
#   1. hedge taker fee 0.0 -> 1.0 (tradexyz assumption, ~1 bps, unverified)
#   2. recorder csv  -> ../logs/minutes-<sym>-xyz.csv  (config-dir-relative,
#      so the path never depends on the starter's cwd)
#   3. trades csv   -> ../logs/trades-<sym>-xyz.csv
#   4. engine log   -> logs/engine-<sym>-xyz.log
# plus per-symbol fixes to comments that name the csv file.
#
# Usage: tools/gen_xyz_configs.sh [SYM ...]   (default: DRAM EWY NBIS SNDK)
set -euo pipefail

PROJ="$(cd "$(dirname "$0")/.." && pwd)"
TEMPLATE="$PROJ/record/config-sndk.yaml"
SYMS="${*:-DRAM EWY NBIS SNDK}"

for sym in $SYMS; do
  lower="$(echo "$sym" | tr 'A-Z' 'a-z')"
  {
    echo "# GENERATED by tools/gen_xyz_configs.sh — do not edit by hand."
    echo "# 再生成：tools/gen_xyz_configs.sh $sym"
    sed \
      -e 's/taker_fee_bps: 0\.0         # Lighter venues: 0; tradexyz: ~1\.0/taker_fee_bps: 1.0         # tradexyz: ~1.0 (assumption, unverified)/' \
      -e "s|csv: \.\./logs/minutes-sndk\.csv|csv: ../logs/minutes-${lower}-xyz.csv|" \
      -e "s|trades_csv: \.\./logs/trades-sndk\.csv|trades_csv: ../logs/trades-${lower}-xyz.csv|" \
      -e "s|file: logs/engine-sndk\.log|file: logs/engine-${lower}-xyz.log|" \
      -e "s|logs/minutes-sndk\.csv|logs/minutes-${lower}-xyz.csv|g" \
      "$TEMPLATE"
  } > "$PROJ/record/config-${lower}-xyz.yaml"
  echo "wrote record/config-${lower}-xyz.yaml"
done
